        private static BossMoveProfile LightProfile(string suffix, string ja, string en, string zh, BossChannelDef[] channels, params BossAction[] actions)
            => new BossMoveProfile("boss_light_elemental." + suffix, LightSetId, new Txt(ja, en, zh), channels, actions);
        private static BossAction LightBeam(BossEvent trigger, string channel, int cd, int delay, int range, int width, int duration = 0, int angle = 0, int count = 1)
            => new BossAction(trigger, BossMechanism.ShapeAttack, BossPayload.Damage, channel, BossShape.Line,
                cooldownMillis: cd, delayMillis: delay, lifetimeMillis: duration, count: count,maxTargets:BossLightBalance.BeamMaxTargets,maxInstances:BossLightBalance.BeamMaxInstances,
                rangeMilli: range, widthMilli: width, angleMilli: angle, element: BossElement.Light);
        private static BossAction LightShield(BossEvent trigger, string channel, int cd)
            => new BossAction(trigger, BossMechanism.Defense, BossPayload.Shield, channel, cooldownMillis: cd,lifetimeMillis:BossLightBalance.ShieldLifetimeMillis,maxTargets:BossLightBalance.ShieldMaxTargets,maxInstances:BossLightBalance.ShieldMaxInstances, followOwner: true, element: BossElement.Light);
        internal static BossMoveProfile[] CreateLightMoves() => new[]
        {
            LightProfile("weapon", "第1記憶（通常攻撃）が敵に命中したとき、その敵の方向へ予告を出し、0.30秒後に長さ7m×幅0.8mの光線を瞬時に放って、攻撃力・魔力の高い方の28%の光属性ダメージを与える。対象ごとに1回命中し、再発動まで5秒かかる。", "When your basic attack (first memory) hits an enemy, fire an instant beam toward that enemy after a 0.30-second warning. The beam is 7m long and 0.8m wide, and deals Light damage equal to 28% of whichever is higher: your Attack or Ability Power, hitting each target once. Cooldown: 5 seconds.", "当第1记忆（通常攻击）命中敌人时，在其方向显示预警，0.30秒后瞬间射出长7m×宽0.8m的光线，造成相当于攻击力与法术强度中较高一方28%的光属性伤害。每个目标只命中1次，冷却5秒。",
                new[] { C("LightBeamAtk",BossLightBalance.LightBeamAtkValue,BossLightBalance.LightBeamAtkCap) }, LightBeam(BossEvent.MainHit,"LightBeamAtk",BossLightBalance.WeaponA0CooldownMillis,BossLightBalance.WeaponA0DelayMillis,BossLightBalance.WeaponA0RangeMilli,BossLightBalance.WeaponA0WidthMilli)),
            LightProfile("armor", "第4記憶の使用中にダメージを受けたとき、攻撃力・魔力の高い方の20%の障壁を2秒間得る。障壁は重ならず、無敵にもならない。再発動まで7秒かかる。", "When you take damage while using your fourth memory, gain a non-stacking shield equal to 20% of whichever is higher: your Attack or Ability Power, for 2 seconds. This does not grant invulnerability. Cooldown: 7 seconds.", "在第4记忆使用期间受到伤害时，获得相当于攻击力与法术强度中较高一方20%的护盾，持续2秒。护盾不叠加，也不会带来无敌。冷却7秒。",
                new[] { C("LightShardShield",BossLightBalance.LightShardShieldValue,BossLightBalance.LightShardShieldCap,BossCoefficientKind.Shield) }, LightShield(BossEvent.NativeDamageTaken,"LightShardShield",BossLightBalance.ArmorA0CooldownMillis)),
            LightProfile("charm", "第2記憶を使ったとき、自身の2m前方に光晶を1個設置する。光晶は3秒間持続し、0.5秒後に、光晶から6m以内の最も近い敵へ長さ6m×幅0.6mの光線を放って、攻撃力・魔力の高い方の24%の光属性ダメージを1回与える。光晶は同時に最大1個までで、召喚物としては扱わない。再発動まで8秒かかる。", "When you use your second memory, place 1 light crystal 2m in front of you for 3 seconds. After 0.5 seconds, it fires a beam 6m long and 0.6m wide toward the nearest enemy within 6m of the crystal, dealing Light damage equal to 24% of whichever is higher: your Attack or Ability Power, once. Only 1 crystal can exist at a time, and it does not count as a summon. Cooldown: 8 seconds.", "使用第2记忆时，在自身前方2m处设置1个光晶。光晶持续3秒，0.5秒后向光晶6m以内最近的敌人射出长6m×宽0.6m的光线，造成1次相当于攻击力与法术强度中较高一方24%的光属性伤害。光晶同时最多存在1个，不视为召唤物。冷却8秒。",
                new[] { C("LightCrystalBeam",BossLightBalance.LightCrystalBeamValue,BossLightBalance.LightCrystalBeamCap) },
                new BossAction(BossEvent.MemoryUse,BossMechanism.Deployable,BossPayload.Deploy,"LightCrystalBeam",cooldownMillis:BossLightBalance.CharmA0CooldownMillis,delayMillis:BossLightBalance.CharmA0DelayMillis,lifetimeMillis:BossLightBalance.CharmA0LifetimeMillis,maxTargets:BossLightBalance.CharmA0MaxTargets,maxInstances:BossLightBalance.CharmA0MaxInstances,rangeMilli:BossLightBalance.CharmA0RangeMilli,widthMilli:BossLightBalance.CharmA0WidthMilli,magnitudeMilli:BossLightBalance.CharmA0MagnitudeMilli,element:BossElement.Light)),
            LightProfile("head", "第2記憶を使ったとき、カーソル位置（自身から8m以内）に、0.45秒後と0.75秒後に予告を伴う半径1.2mの落雷を落とし、それぞれ攻撃力・魔力の高い方の16%の光属性ダメージを与える。再発動まで7秒かかる。", "When you use your second memory, call down lightning at the cursor position within 8m of you after 0.45 and 0.75 seconds, with a warning before each strike. Each strike covers a 1.2m radius and deals Light damage equal to 16% of whichever is higher: your Attack or Ability Power. Cooldown: 7 seconds.", "使用第2记忆时，在光标位置（自身8m以内）降下半径1.2m的落雷，0.45秒后和0.75秒后各1次，每次都伴随预警，各造成相当于攻击力与法术强度中较高一方16%的光属性伤害。冷却7秒。",
                new[] { C("LightLightning",BossLightBalance.LightLightningValue,BossLightBalance.LightLightningCap) },
