        };
        internal static BossRewardProfile[] CreateLightRewards()
        {
            var turn = new BossRewardAction(BossRewardActionKind.NativeSpeed,BossLightBalance.RewardTurnValueMilli,BossLightBalance.RewardTurnCapMilli,magnitudeMilli:BossLightBalance.RewardTurnMagnitudeMilli);
            var width = new BossRewardAction(BossRewardActionKind.NativeState,BossLightBalance.RewardWidthValueMilli,BossLightBalance.RewardWidthCapMilli,order:1,magnitudeMilli:BossLightBalance.RewardWidthMagnitudeMilli);
            var pulse = new BossRewardAction(BossRewardActionKind.NativeDamage,BossLightBalance.RewardPulseValueMilli,BossLightBalance.RewardPulseCapMilli,BossLightBalance.RewardPulseCooldownMillis,durationMillis:BossLightBalance.RewardPulseDurationMillis,count:BossLightBalance.RewardPulseCount,rangeMilli:BossLightBalance.RewardPulseRangeMilli,order:2,magnitudeMilli:BossLightBalance.RewardPulseMagnitudeMilli,intervalMillis:BossLightBalance.RewardPulseIntervalMillis,targetCapMilli:BossLightBalance.RewardPulseTargetCapMilli,budgetMilli:BossLightBalance.RewardPulseBudgetMilli);
            return new[] { new BossRewardProfile(LightRewardId,LightSetId,"St_U_WorldCracker",BossRewardAdapter.WorldCracker,new[]
            {
                new BossRewardStage(1,new Txt("装備中の「WorldCracker」による本体光線の旋回速度が、毎秒30°増える（元の旋回速度の最大1.5倍まで）。本体の詠唱、消費、持続時間は変わらない。", "Increase the turning speed of your equipped WorldCracker's main beam by 30° per second, up to 1.5 times its original turning speed. Its casting, resource cost, and duration remain unchanged.", "装备中的“WorldCracker”的本体光线旋回速度每秒增加30°（最高为原旋回速度的1.5倍）。本体的咏唱、消耗与持续时间不变。"),new[] { turn }),
                new BossRewardStage(2,new Txt("固有報酬の段階1の効果に加え、同じ光線の判定半径が0.30m広がる（元の半径の最大1.5倍まで）。射程やヒット間隔は変わらない。", "In addition to boss reward stage 1, increase the same beam's hit radius by 0.30m, up to 1.5 times its original radius. Its range and time between hits remain unchanged.", "在固有奖励阶段1的效果之上，同一光线的判定半径扩大0.30m（最高为原半径的1.5倍）。射程与命中间隔不变。"),new[] { turn,width }),
                new BossRewardStage(3,new Txt("固有報酬の段階2の効果に加え、同じ敵に本体の攻撃が1秒以内の間隔で3回命中すると（最大3体まで記録）、直前の着弾地点に予告を出し、0.35秒後に半径1.8mの光の波動を放って、攻撃力・魔力の高い方の45%の光属性ダメージを与える。再発動まで6秒かかり、光線1回につき最大2回までである。詠唱が中断されると、待機中の波動はキャンセルされる。", "In addition to boss reward stage 2, when the main beam hits the same enemy 3 times with no more than 1 second between hits, release a pulse of light at the most recent impact point after a 0.35-second warning. The pulse deals Light damage equal to 45% of whichever is higher: your Attack or Ability Power, in a 1.8m radius. Track hits on up to 3 enemies at a time. Cooldown: 6 seconds, with at most 2 pulses per beam use. Interrupting the cast cancels any pulses waiting to occur.", "在固有奖励阶段2的效果之上，本体攻击以不超过1秒的间隔命中同一敌人3次时（最多记录3名敌人），在最后落点显示预警，0.35秒后放出半径1.8m的光之波动，造成相当于攻击力与法术强度中较高一方45%的光属性伤害。冷却6秒，每次光线最多触发2次。咏唱被打断时，待发的波动会被取消。"),new[] { turn,width,pulse }),
            }) };
        }
